// Judul: Kendali Aktuator Digital Menggunakan ESP32
// dengan LED dan Buzzer
// Kelompok 2
// Anggota: Vallian, Ahmad Reyhan

#define LED_PIN 2
#define BUZZER_PIN 4

void setup() {
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
}

void loop() {
  // Semua ON
  digitalWrite(LED_PIN, HIGH);
  digitalWrite(BUZZER_PIN, HIGH);

  delay(2000);

  // Semua OFF
  digitalWrite(LED_PIN, LOW);
  digitalWrite(BUZZER_PIN, LOW);

  delay(2000);
}
